import { describe, expect, it } from 'vitest'
import TRANSLATIONS_DE from './de'
import TRANSLATIONS_EN from './en'

const LONG_EN =
  'An agent will generate content using artificial intelligence. That content can contain mistakes or inaccurate details. Always verify critical information, legal facts, or professional advice before use.'
const SHORT_EN =
  'NOTE: Output is generated by AI. Please verify as errors may occur.'

describe('ai generated notice copy', () => {
  it('matches the approved English strings', () => {
    expect(TRANSLATIONS_EN.ai_generated_notice_long).toBe(LONG_EN)
    expect(TRANSLATIONS_EN.ai_generated_notice_short).toBe(SHORT_EN)
  })

  it('has German strings that differ from English', () => {
    expect(TRANSLATIONS_DE.ai_generated_notice_long.length).toBeGreaterThan(0)
    expect(TRANSLATIONS_DE.ai_generated_notice_short.length).toBeGreaterThan(0)
    expect(TRANSLATIONS_DE.ai_generated_notice_long).not.toBe(LONG_EN)
    expect(TRANSLATIONS_DE.ai_generated_notice_short).not.toBe(SHORT_EN)
  })
})
